candidates.raw:
size_t i;
double speed, absv, accel, pred, maxv, predmax;
double vals[3], lim;
adcs_vec3_t h;
unint32 trip_mask, sat_mask, slew_mask;
int invalid = 0;
int enter_active = 0;
int enter_recovery = 0;
int enter_off = 0;
int do_active_output = 0;

/* validate config */
if ((!isfinite(wo_config.release_rad_s)) || (!isfinite(wo_config.warn_rad_s)) ||
    (!isfinite(wo_config.trip_rad_s)) || (wo_config.release_rad_s < 0.0) ||
    (!(wo_config.release_rad_s < wo_config.warn_rad_s)) ||
    (!(wo_config.warn_rad_s < wo_config.trip_rad_s)) ||
    (!isfinite(wo_config.dt_s)) || (wo_config.dt_s <= 0.0) ||
    (!isfinite(wo_config.prediction_horizon_s)) || (wo_config.prediction_horizon_s <= 0.0) ||
    (!isfinite(wo_config.torque_limit)) || (wo_config.torque_limit <= 0.0) ||
    (!isfinite(wo_config.torque_slew)) || (wo_config.torque_slew <= 0.0) ||
    (!isfinite(wo_config.gain)) || (wo_config.gain < 0.0) ||
    (wo_config.minimum_active_cycles < 1U) || (wo_config.minimum_active_cycles > 100U) ||
    (wo_config.release_cycles < 1U) || (wo_config.release_cycles > 100U) ||
    (wo_config.recovery_cycles < 1U) || (wo_config.recovery_cycles > 100U) ||
    ((wo_input.enable != 0) && (wo_input.enable != 1))) {
    invalid = 1;
}

/* validate input and sum exactly four wheels */
if (!invalid) {
    if ((wo_input.wheels == NULL) || (wo_input.count != 4U)) {
        invalid = 1;
    } else {
        for (i = 0; i < 4U; i++) {
            if ((!isfinite(wo_input.wheels[i].speed_rad_s)) ||
                (!isfinite(wo_input.wheels[i].inertia_kg_m2)) ||
                (wo_input.wheels[i].inertia_kg_m2 < 0.0))
                invalid = 1;
        }
    }
    if (!invalid) {
        if (adcs_wheel_momentum(wo_input.wheels, wo_input.count, &h) != ADCS_OK)
            invalid = 1;
        else if ((!isfinite(h.x)) || (!isfinite(h.y)) || (!isfinite(h.z)))
            invalid = 1;
    }
}

if (invalid) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

if (wo_input.enable == 0) {
    wo_state.mode = WO_OFF;
    wo_output.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.elapsed = 0U;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < 4U; i++)
        wo_state.previous_speed_rad_s[i] = 0.0;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

/* compute speed/acceleration/predicted */
maxv = 0.0;
predmax = 0.0;
trip_mask = 0U;
if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++) {
        speed = wo_input.wheels[i].speed_rad_s;
        wo_state.previous_speed_rad_s[i] = speed;
        wo_output.acceleration_rad_s2[i] = 0.0;
        pred = speed;
        wo_output.predicted_speed_rad_s[i] = pred;
        absv = fabs(speed);
        if (absv > maxv) maxv = absv;
        if (fabs(pred) > predmax) predmax = fabs(pred);
        if (fabs(pred) >= wo_config.trip_rad_s)
            trip_mask |= (unint32)(1U << i);
    }
    wo_state.history_initialized = 1;
} else {
    for (i = 0; i < 4U; i++) {
        speed = wo_input.wheels[i].speed_rad_s;
        accel = (speed - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
        wo_output.acceleration_rad_s2[i] = accel;
        pred = speed + accel * wo_config.prediction_horizon_s;
        wo_output.predicted_speed_rad_s[i] = pred;
        wo_state.previous_speed_rad_s[i] = speed;
        absv = fabs(speed);
        if (absv > maxv) maxv = absv;
        if (fabs(pred) > predmax) predmax = fabs(pred);
        if (fabs(pred) >= wo_config.trip_rad_s)
            trip_mask |= (unint32)(1U << i);
    }
}

wo_output.maximum_speed = maxv;
wo_output.predicted_maximum_speed = predmax;
wo_output.predicted_trip_mask = trip_mask;
wo_output.momentum = h;
wo_output.momentum_norm = sqrt(h.x * h.x + h.y * h.y + h.z * h.z);

sat_mask = 0U;
slew_mask = 0U;
do_active_output = 0;

/* state machine */
switch (wo_state.mode) {
case WO_OFF:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else if (predmax >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
        wo_state.clean = 0U;
    }
    break;
case WO_WATCH:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else if (predmax < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
        wo_state.clean = 0U;
    }
    break;
case WO_ACTIVE:
    wo_state.elapsed = wo_state.elapsed + 1U;
    if ((predmax < wo_config.trip_rad_s) &&
        (maxv <= wo_config.release_rad_s) &&
        (predmax <= wo_config.release_rad_s) &&
        (wo_state.elapsed >= wo_config.minimum_active_cycles)) {
        wo_state.clean = wo_state.clean + 1U;
    } else {
        wo_state.clean = 0U;
    }
    if (wo_state.clean >= wo_config.release_cycles) {
        enter_recovery = 1;
    } else {
        do_active_output = 1;
    }
    break;
case WO_RECOVERY:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else {
        wo_state.recovery_count = wo_state.recovery_count + 1U;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            enter_off = 1;
        } else {
            /* zero command through the same slew limiter */
            wo_state.clean = 0U;
        }
    }
    break;
default:
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

if (enter_active) {
    wo_state.mode = WO_ACTIVE;
    wo_state.elapsed = 0U;
    wo_state.clean = 0U;
    do_active_output = 1;
} else if (enter_recovery) {
    wo_state.mode = WO_RECOVERY;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = WO_RECOVERY;
    return;
} else if (enter_off) {
    wo_state.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.elapsed = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = WO_OFF;
    return;
}

if (do_active_output) {
    /* magnitude limit per axis */
    vals[0] = -wo_config.gain * h.x;
    vals[1] = -wo_config.gain * h.y;
    vals[2] = -wo_config.gain * h.z;
    for (i = 0; i < 3U; i++) {
        if (vals[i] > wo_config.torque_limit) {
            vals[i] = wo_config.torque_limit;
            sat_mask |= (unint32)(1U << i);
        } else if (vals[i] < -wo_config.torque_limit) {
            vals[i] = -wo_config.torque_limit;
            sat_mask |= (unint32)(1U << i);
        }
    }
    /* slew limit from previous body torque */
    {
        double prev[3];
        prev[0] = wo_state.previous_torque.x;
        prev[1] = wo_state.previous_torque.y;
        prev[2] = wo_state.previous_torque.z;
        diff = wo_config.torque_slew * wo_config.dt_s;
        for (i = 0; i < 3U; i++) {
            lim = vals[i] - prev[i];
            if (lim > diff) {
                vals[i] = prev[i] + diff;
                slew_mask |= (unint32)(1U << i);
            } else if (lim < -diff) {
                vals[i] = prev[i] - diff;
                slew_mask |= (unint32)(1U << i);
            } else {
                vals[i] = vals[i];
            }
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = sat_mask;
    wo_output.slew_mask = slew_mask;
    wo_output.mode = WO_ACTIVE;
} else if (wo_state.mode == WO_RECOVERY) {
    /* zero command through the same slew limiter */
    double prev[3];
    prev[0] = wo_state.previous_torque.x;
    prev[1] = wo_state.previous_torque.y;
    prev[2] = wo_state.previous_torque.z;
    diff = wo_config.torque_slew * wo_config.dt_s;
    for (i = 0; i < 3U; i++) {
        lim = 0.0 - prev[i];
        if (lim > diff) {
            vals[i] = prev[i] + diff;
            slew_mask |= (unint32)(1U << i);
        } else if (lim < -diff) {
            vals[i] = prev[i] - diff;
            slew_mask |= (unint32)(1U << i);
        } else {
            vals[i] = 0.0;
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = slew_mask;
    wo_output.mode = WO_RECOVERY;
} else {
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = wo_state.mode;
}

