adcs_vec3_t h;
uint32_t trip_mask, sat_mask, slew_mask;
int invalid = 0;
int enter_active = 0;
int enter_recovery = 0;
int enter_off = 0;
int do_active_output = 0;

/* validate config */
if ((!isfinite(wo_config.release_rad_s)) || (!isfinite(wo_config.warn_rad_s)) ||
    (!isfinite(wo_config.trip_rad_s)) || (wo_config.release_rad_s < 0.0) ||
    (!(wo_config.release_rad_s < wo_config.warn_rad_s)) ||
    (!(wo_config.warn_rad_s < wo_config.trip_rad_s)) ||
    (!isfinite(wo_config.dt_s)) || (wo_config.dt_s <= 0.0) ||
    (!isfinite(wo_config.prediction_horizon_s)) || (wo_config.prediction_horizon_s <= 0.0) ||
    (!isfinite(wo_config.torque_limit)) || (wo_config.torque_limit <= 0.0) ||
    (!isfinite(wo_config.torque_slew)) || (wo_config.torque_slew <= 0.0) ||
    (!isfinite(wo_config.gain)) || (wo_config.gain < 0.0) ||
    (wo_config.minimum_active_cycles < 1U) || (wo_config.minimum_active_cycles > 100U) ||
    (wo_config.release_cycles < 1U) || (wo_config.release_cycles > 100U) ||
    (wo_config.recovery_cycles < 1U) || (wo_config.recovery_cycles > 100U) ||
    ((wo_input.enable != 0) && (wo_input.enable != 1))) {
    invalid = 1;
}

/* validate input and sum exactly four wheels */
if (!invalid) {
    if ((wo_input.wheels == NULL) || (wo_input.count != 4U)) {
        invalid = 1;
    } else {
        for (i = 0; i < 4U; i++) {
            if ((!isfinite(wo_input.wheels[i].speed_rad_s)) ||
                (!isfinite(wo_input.wheels[i].inertia_kg_m2)) ||
                (wo_input.wheels[i].inertia_kg_m2 < 0.0))
                invalid = 1;
        }
    }
    if (!invalid) {
        if (adcs_wheel_momentum(wo_input.wheels, wo_input.count, &h) != ADCS_OK)
            invalid = 1;
        else if ((!isfinite(h.x)) || (!isfinite(h.y)) || (!isfinite(h.z)))
            invalid = 1;
        else {
            /* momentum valid, no action */
        }
    } else {
        /* already invalid, no action */
    }
}

if (invalid) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

if (wo_input.enable == 0) {
    wo_state.mode = WO_OFF;
    wo_output.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.elapsed = 0U;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < 4U; i++)
        wo_state.previous_speed_rad_s[i] = 0.0;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
} else {
    /* enabled: fall through to the main supervisor */
}

/* compute speed/acceleration/predicted */
maxv = 0.0;
predmax = 0.0;
trip_mask = 0U;
if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++) {
        speed = wo_input.wheels[i].speed_rad_s;
        wo_state.previous_speed_rad_s[i] = speed;
        wo_output.acceleration_rad_s2[i] = 0.0;
        pred = speed;
        wo_output.predicted_speed_rad_s[i] = pred;
        absv = fabs(speed);
        if (absv > maxv) maxv = absv;
        if (fabs(pred) > predmax) predmax = fabs(pred);
        if (fabs(pred) >= wo_config.trip_rad_s)
            trip_mask |= (uint32_t)(1U << i);
    }
    wo_state.history_initialized = 1;
} else {
    for (i = 0; i < 4U; i++) {
        speed = wo_input.wheels[i].speed_rad_s;
        accel = (speed - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
        wo_output.acceleration_rad_s2[i] = accel;
        pred = speed + accel * wo_config.prediction_horizon_s;
        wo_output.predicted_speed_rad_s[i] = pred;
        wo_state.previous_speed_rad_s[i] = speed;
        absv = fabs(speed);
        if (absv > maxv) maxv = absv;
        if (fabs(pred) > predmax) predmax = fabs(pred);
        if (fabs(pred) >= wo_config.trip_rad_s)
            trip_mask |= (uint32_t)(1U << i);
    }
}

wo_output.maximum_speed = maxv;
wo_output.predicted_maximum_speed = predmax;
wo_output.predicted_trip_mask = trip_mask;
wo_output.momentum = h;
wo_output.momentum_norm = sqrt(h.x * h.x + h.y * h.y + h.z * h.z);

sat_mask = 0U;
slew_mask = 0U;
do_active_output = 0;

/* state machine */
switch (wo_state.mode) {
case WO_OFF:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else if (predmax >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
        wo_state.clean = 0U;
    } else {
        /* stay in WO_OFF, no transition */
    }
    break;
case WO_WATCH:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else if (predmax < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
        wo_state.clean = 0U;
    } else {
        /* stay in WO_WATCH, no transition */
    }
    break;
case WO_ACTIVE:
    wo_state.elapsed = wo_state.elapsed + 1U;
    if ((predmax < wo_config.trip_rad_s) &&
        (maxv <= wo_config.release_rad_s) &&
        (predmax <= wo_config.release_rad_s) &&
        (wo_state.elapsed >= wo_config.minimum_active_cycles)) {
        wo_state.clean = wo_state.clean + 1U;
    } else {
        wo_state.clean = 0U;
    }
    if (wo_state.clean >= wo_config.release_cycles) {
        enter_recovery = 1;
    } else {
        do_active_output = 1;
    }
    break;
case WO_RECOVERY:
    if (predmax >= wo_config.trip_rad_s) {
        enter_active = 1;
    } else {
        wo_state.recovery_count = wo_state.recovery_count + 1U;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            enter_off = 1;
        } else {
            /* zero command through the same slew limiter */
            wo_state.clean = 0U;
        }
    }
    break;
default:
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

if (enter_active) {
    wo_state.mode = WO_ACTIVE;
    wo_state.elapsed = 0U;
    wo_state.clean = 0U;
    do_active_output = 1;
} else if (enter_recovery) {
    wo_state.mode = WO_RECOVERY;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = WO_RECOVERY;
    return;
} else if (enter_off) {
    wo_state.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.clean = 0U;
    wo_state.recovery_count = 0U;
    wo_state.elapsed = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = WO_OFF;
    return;
} else {
    /* no transition this cycle: keep current mode */
    wo_output.mode = wo_state.mode;
}

if (do_active_output) {
    /* magnitude limit per axis */
    vals[0] = -wo_config.gain * h.x;
    vals[1] = -wo_config.gain * h.y;
    vals[2] = -wo_config.gain * h.z;
    for (i = 0; i < 3U; i++) {
        if (vals[i] > wo_config.torque_limit) {
            vals[i] = wo_config.torque_limit;
            sat_mask |= (uint32_t)(1U << i);
        } else if (vals[i] < -wo_config.torque_limit) {
            vals[i] = -wo_config.torque_limit;
            sat_mask |= (uint32_t)(1U << i);
        }
    }
    /* slew limit from previous body torque */
    {
        double prev[3];
        prev[0] = wo_state.previous_torque.x;
        prev[1] = wo_state.previous_torque.y;
        prev[2] = wo_state.previous_torque.z;
        diff = wo_config.torque_slew * wo_config.dt_s;
        for (i = 0; i < 3U; i++) {
            lim = vals[i] - prev[i];
            if (lim > diff) {
                vals[i] = prev[i] + diff;
                slew_mask |= (uint32_t)(1U << i);
            } else if (lim < -diff) {
                vals[i] = prev[i] - diff;
                slew_mask |= (uint32_t)(1U << i);
            } else {
                vals[i] = vals[i];
            }
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = sat_mask;
    wo_output.slew_mask = slew_mask;
    wo_output.mode = WO_ACTIVE;
} else if (wo_state.mode == WO_RECOVERY) {
    /* zero command through the same slew limiter */
    double prev[3];
    prev[0] = wo_state.previous_torque.x;
    prev[1] = wo_state.previous_torque.y;
    prev[2] = wo_state.previous_torque.z;
    diff = wo_config.torque_slew * wo_config.dt_s;
    for (i = 0; i < 3U; i++) {
        lim = 0.0 - prev[i];
        if (lim > diff) {
            vals[i] = prev[i] + diff;
            slew_mask |= (uint32_t)(1U << i);
        } else if (lim < -diff) {
            vals[i] = prev[i] - diff;
            slew_mask |= (uint32_t)(1U << i);
        } else {
            vals[i] = 0.0;
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = slew_mask;
    wo_output.mode = WO_RECOVERY;
} else {
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_state.previous_torque = wo_output.torque;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.mode = wo_state.mode;
}

candidates.raw:
{
    size_t i;
    int fault = 0;
    adcs_wheel_t wheels4[4];
    adcs_vec3_t momentum;
    double acc[4], pred[4];
    double cur_max, pred_max;
    unint32 trip_mask;
    double cfg_release, cfg_warn, cfg_trip, cfg_dt, cfg_horizon, cfg_gain, cfg_tlimit, cfg_slew;
    unint32 cfg_minact, cfg_relcyc, cfg_recvyc;

    cfg_release = wo_config.release_rad_s;
    cfg_warn = wo_config.warn_rad_s;
    cfg_trip = wo_config.trip_rad_s;
    cfg_dt = wo_config.dt_s;
    cfg_horizon = wo_config.prediction_horizon_s;
    cfg_gain = wo_config.gain;
    cfg_tlimit = wo_config.torque_limit;
    cfg_slew = wo_config.torque_slew;
    cfg_minact = wo_config.minimum_active_cycles;
    cfg_relcyc = wo_config.release_cycles;
    cfg_recvyc = wo_config.recovery_cycles;

    if (!isfinite(cfg_release) || !isfinite(cfg_warn) || !isfinite(cfg_trip) ||
        !isfinite(cfg_dt) || !isfinite(cfg_horizon) || !isfinite(cfg_gain) ||
        !isfinite(cfg_tlimit) || !isfinite(cfg_slew) ||
        !(cfg_release >= 0.0) || !(cfg_release < cfg_warn) || !(cfg_warn < cfg_trip) ||
        !(cfg_dt > 0.0) || !(cfg_horizon > 0.0) || !(cfg_tlimit > 0.0) || !(cfg_slew > 0.0) ||
        !(cfg_gain >= 0.0) ||
        !(cfg_minact >= 1U) || (cfg_minact > 100U) ||
        !(cfg_relcyc >= 1U) || (cfg_relcyc > 100U) ||
        !(cfg_recvyc >= 1U) || (cfg_recvyc > 100U))
        fault = 1;

    if (wo_input.enable != 0 && wo_input.enable != 1)
        fault = 1;

    if (wo_input.wheels == NULL || wo_input.count != 4U)
        fault = 1;

    if (fault) {
        wo_state.mode = WO_FAULT;
        wo_state.history_initialized = 0;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
        wo_output.mode = WO_FAULT;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        return;
    }

    if (wo_input.enable == 0) {
        wo_state.mode = WO_OFF;
        wo_state.history_initialized = 0;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
        wo_output.mode = WO_OFF;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        return;
    }

    for (i = 0; i < 4U; i++) {
        wheels4[i] = wo_input.wheels[i];
        if ((!isfinite(wheels4[i].inertia_kg_m2)) ||
            (wheels4[i].inertia_kg_m2 < 0.0) ||
            (!isfinite(wheels4[i].speed_rad_s)) ||
            (!isfinite(wheels4[i].axis_body.x)) ||
            (!isfinite(wheels4[i].axis_body.y)) ||
            (!isfinite(wheels4[i].axis_body.z))) {
            fault = 1;
        }
    }

    if (fault) {
        wo_state.mode = WO_FAULT;
        wo_state.history_initialized = 0;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
        wo_output.mode = WO_FAULT;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        return;
    }

    if (!wo_state.history_initialized) {
        for (i = 0; i < 4U; i++) {
            wo_state.previous_speed_rad_s[i] = wheels4[i].speed_rad_s;
            acc[i] = 0.0;
            pred[i] = wheels4[i].speed_rad_s;
        }
        wo_state.history_initialized = 1;
        wo_state.mode = WO_OFF;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};

        cur_max = 0.0;
        pred_max = 0.0;
        trip_mask = 0U;
        for (i = 0; i < 4U; i++) {
            if (fabs(wheels4[i].speed_rad_s) > cur_max)
                cur_max = fabs(wheels4[i].speed_rad_s);
            if (fabs(pred[i]) > pred_max)
                pred_max = fabs(pred[i]);
            if (fabs(pred[i]) >= cfg_trip)
                trip_mask |= (unint32)(1U << i);
        }

        wo_output.mode = WO_OFF;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = cur_max;
        wo_output.predicted_maximum_speed = pred_max;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.predicted_trip_mask = trip_mask;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = acc[i];
            wo_output.predicted_speed_rad_s[i] = pred[i];
        }
        return;
    }

    if (adcs_wheel_momentum(wheels4, 4U, &momentum) != ADCS_OK)
        fault = 1;

    if (!fault && (!isfinite(momentum.x) || !isfinite(momentum.y) || !isfinite(momentum.z)))
        fault = 1;

    if (fault) {
        wo_state.mode = WO_FAULT;
        wo_state.history_initialized = 0;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
        wo_output.mode = WO_FAULT;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        return;
    }

    cur_max = 0.0;
    pred_max = 0.0;
    trip_mask = 0U;
    for (i = 0; i < 4U; i++) {
        acc[i] = (wheels4[i].speed_rad_s - wo_state.previous_speed_rad_s[i]) / cfg_dt;
        pred[i] = wheels4[i].speed_rad_s + acc[i] * cfg_horizon;
        if (fabs(wheels4[i].speed_rad_s) > cur_max)
            cur_max = fabs(wheels4[i].speed_rad_s);
        if (fabs(pred[i]) > pred_max)
            pred_max = fabs(pred[i]);
        if (fabs(pred[i]) >= cfg_trip)
            trip_mask |= (unint32)(1U << i);
        wo_state.previous_speed_rad_s[i] = wheels4[i].speed_rad_s;
    }

    switch (wo_state.mode) {
    case WO_OFF:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else if (pred_max >= cfg_warn) {
            wo_state.mode = WO_WATCH;
            wo_state.clean = 0U;
        }
        break;
    case WO_WATCH:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else if (pred_max < cfg_warn) {
            wo_state.mode = WO_OFF;
            wo_state.clean = 0U;
        }
        break;
    case WO_ACTIVE:
        wo_state.elapsed = wo_state.elapsed + 1U;
        if (wo_state.elapsed >= cfg_minact &&
            cur_max <= cfg_release && pred_max <= cfg_release) {
            wo_state.clean = wo_state.clean + 1U;
        } else {
            wo_state.clean = 0U;
        }
        if (wo_state.clean >= cfg_relcyc) {
            wo_state.mode = WO_RECOVERY;
            wo_state.clean = 0U;
            wo_state.recovery_count = 0U;
        }
        break;
    case WO_RECOVERY:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else {
            wo_state.recovery_count = wo_state.recovery_count + 1U;
            if (wo_state.recovery_count >= cfg_recvyc) {
                wo_state.mode = WO_OFF;
                wo_state.clean = 0U;
                wo_state.recovery_count = 0U;
            }
        }
        break;
    default:
        wo_state.mode = WO_FAULT;
        break;
    }

    {
        adcs_vec3_t desired, slewed;
        double v[3], dv[3], prev[3];
        unint32 sat_mask = 0U, slew_mask = 0U;
        int active;
        double maxdelta;

        if (wo_state.mode == WO_FAULT) {
            wo_state.history_initialized = 0;
