            if (fabs(pred[i]) >= cfg_trip)
                trip_mask |= (uint32_t)(1U << i);
        }

        wo_output.mode = WO_OFF;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = cur_max;
        wo_output.predicted_maximum_speed = pred_max;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.predicted_trip_mask = trip_mask;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = acc[i];
            wo_output.predicted_speed_rad_s[i] = pred[i];
        }
        return;
    }

    if (adcs_wheel_momentum(wheels4, 4U, &momentum) != ADCS_OK)
        fault = 1;

    if (!fault && (!isfinite(momentum.x) || !isfinite(momentum.y) || !isfinite(momentum.z)))
        fault = 1;

    if (fault) {
        wo_state.mode = WO_FAULT;
        wo_state.history_initialized = 0;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
        wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
        wo_output.mode = WO_FAULT;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        wo_output.momentum = (adcs_vec3_t){0, 0, 0};
        wo_output.torque = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm = 0.0;
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        return;
    }

    cur_max = 0.0;
    pred_max = 0.0;
    trip_mask = 0U;
    for (i = 0; i < 4U; i++) {
        acc[i] = (wheels4[i].speed_rad_s - wo_state.previous_speed_rad_s[i]) / cfg_dt;
        pred[i] = wheels4[i].speed_rad_s + acc[i] * cfg_horizon;
        if (fabs(wheels4[i].speed_rad_s) > cur_max)
            cur_max = fabs(wheels4[i].speed_rad_s);
        if (fabs(pred[i]) > pred_max)
            pred_max = fabs(pred[i]);
        if (fabs(pred[i]) >= cfg_trip) {
            uint32_t trip_bit = (uint32_t)1U << (uint32_t)i;
            trip_mask = trip_mask | trip_bit;
        }
        wo_state.previous_speed_rad_s[i] = wheels4[i].speed_rad_s;
    }

    switch (wo_state.mode) {
    case WO_OFF:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else if (pred_max >= cfg_warn) {
            wo_state.mode = WO_WATCH;
            wo_state.clean = 0U;
        } else {
            /* OFF: no action, remains off */
        }
        break;
    case WO_WATCH:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else if (pred_max < cfg_warn) {
            wo_state.mode = WO_OFF;
            wo_state.clean = 0U;
        } else {
            /* WATCH: no action, remains in watch */
        }
        break;
    case WO_ACTIVE:
        wo_state.elapsed = (uint32_t)(wo_state.elapsed + 1U);
        if (wo_state.elapsed >= cfg_minact &&
            cur_max <= cfg_release && pred_max <= cfg_release) {
            wo_state.clean = (uint32_t)(wo_state.clean + 1U);
        } else {
            wo_state.clean = 0U;
        }
        if (wo_state.clean >= cfg_relcyc) {
            wo_state.mode = WO_RECOVERY;
            wo_state.clean = 0U;
            wo_state.recovery_count = 0U;
        } else {
            /* ACTIVE: continued release evidence not yet sufficient */
        }
        break;
    case WO_RECOVERY:
        if (pred_max >= cfg_trip) {
            wo_state.mode = WO_ACTIVE;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else {
            wo_state.recovery_count = (uint32_t)(wo_state.recovery_count + 1U);
            if (wo_state.recovery_count >= cfg_recvyc) {
                wo_state.mode = WO_OFF;
                wo_state.clean = 0U;
                wo_state.recovery_count = 0U;
            } else {
                /* RECOVERY: not yet reached recovery_cycles */
            }
        }
        break;
    default:
        wo_state.mode = WO_FAULT;
        break;
    }

    {
        adcs_vec3_t desired, slewed;
        double v[3], dv[3], prev[3];
        uint32_t sat_mask = 0U, slew_mask = 0U;
        int active;
        double maxdelta;

        if (wo_state.mode == WO_FAULT) {
            wo_state.history_initialized = 0;
            desired = (adcs_vec3_t){0, 0, 0};
        } else if (wo_state.mode == WO_ACTIVE) {
            desired = adcs_vec3_scale(&momentum, -cfg_gain);
        } else {
            desired = (adcs_vec3_t){0, 0, 0};
        }

        active = (wo_state.mode == WO_ACTIVE);
        v[0] = desired.x;
        v[1] = desired.y;
        v[2] = desired.z;

        for (i = 0; i < 3U; i++) {
            if (active) {
                if (v[i] > cfg_tlimit) {
                    v[i] = cfg_tlimit;
                    sat_mask |= (uint32_t)(1U << i);
                } else if (v[i] < -cfg_tlimit) {
                    v[i] = -cfg_tlimit;
                    sat_mask |= (uint32_t)(1U << i);
                } else {
                    /* within magnitude limit */
                }
            }
        }

        prev[0] = wo_state.previous_torque.x;
        prev[1] = wo_state.previous_torque.y;
        prev[2] = wo_state.previous_torque.z;
        maxdelta = cfg_slew * cfg_dt;
        for (i = 0; i < 3U; i++) {
            dv[i] = v[i] - prev[i];
            if (dv[i] > maxdelta) {
                dv[i] = maxdelta;
                slew_mask |= (uint32_t)(1U << i);
            } else if (dv[i] < -maxdelta) {
                dv[i] = -maxdelta;
                slew_mask |= (uint32_t)(1U << i);
            } else {
                /* within slew limit */
            }
        }
        slewed = (adcs_vec3_t){prev[0] + dv[0], prev[1] + dv[1], prev[2] + dv[2]};

        wo_output.mode = wo_state.mode;
        wo_output.clean = wo_state.clean;
        wo_output.elapsed = wo_state.elapsed;
        wo_output.recovery_count = wo_state.recovery_count;
        wo_output.maximum_speed = cur_max;
        wo_output.predicted_maximum_speed = pred_max;
        wo_output.momentum = (wo_state.mode == WO_FAULT) ? (adcs_vec3_t){0, 0, 0} : momentum;
        wo_output.momentum_norm = adcs_vec3_norm(&wo_output.momentum);
        wo_output.torque = (wo_state.mode == WO_FAULT) ? (adcs_vec3_t){0, 0, 0} : slewed;
        wo_output.predicted_trip_mask = trip_mask;
        wo_output.saturation_mask = (wo_state.mode == WO_FAULT) ? 0U : sat_mask;
        wo_output.slew_mask = (wo_state.mode == WO_FAULT) ? 0U : slew_mask;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = acc[i];
            wo_output.predicted_speed_rad_s[i] = pred[i];
        }
        wo_state.previous_torque = (wo_state.mode == WO_FAULT)
                                       ? (adcs_vec3_t){0, 0, 0}
                                       : slewed;
    }
    return;
}

candidates.raw:
size_t i;
unint32 predicted_trip_mask = 0U;
unint32 saturation_mask = 0U;
unint32 slew_mask = 0U;
double accel[4];
double predicted[4];
double current_max;
double predicted_max;
adcs_vec3_t cluster_momentum;
adcs_vec3_t torque_cmd;
adcs_vec3_t limited;
double axis_vals[3];
double prev_vals[3];
double tmp;
int valid = 1;

cluster_momentum = (adcs_vec3_t){0.0, 0.0, 0.0};

/* 输入与配置校验 */
if ((wo_input.wheels == NULL) || (wo_input.count != 4U) ||
    (wo_input.enable != 0 && wo_input.enable != 1)) {
    valid = 0;
}
if (valid) {
    if (!(isfinite(wo_config.release_rad_s) && wo_config.release_rad_s >= 0.0) ||
        !(isfinite(wo_config.warn_rad_s)) || !(isfinite(wo_config.trip_rad_s)) ||
        !(wo_config.release_rad_s < wo_config.warn_rad_s) ||
        !(wo_config.warn_rad_s < wo_config.trip_rad_s)) valid = 0;
    if (!(isfinite(wo_config.dt_s) && wo_config.dt_s > 0.0)) valid = 0;
    if (!(isfinite(wo_config.prediction_horizon_s) && wo_config.prediction_horizon_s > 0.0)) valid = 0;
    if (!(isfinite(wo_config.torque_limit) && wo_config.torque_limit > 0.0)) valid = 0;
    if (!(isfinite(wo_config.torque_slew) && wo_config.torque_slew > 0.0)) valid = 0;
    if (!(isfinite(wo_config.gain) && wo_config.gain >= 0.0)) valid = 0;
    if (wo_config.minimum_active_cycles < 1U || wo_config.minimum_active_cycles > 100U) valid = 0;
    if (wo_config.release_cycles < 1U || wo_config.release_cycles > 100U) valid = 0;
    if (wo_config.recovery_cycles < 1U || wo_config.recovery_cycles > 100U) valid = 0;
}
if (valid) {
    for (i = 0; i < 4U; i++) {
        if ((!isfinite(wo_input.wheels[i].speed_rad_s)) ||
            (!isfinite(wo_input.wheels[i].inertia_kg_m2)) ||
            (wo_input.wheels[i].inertia_kg_m2 < 0.0)) {
            valid = 0;
            break;
        }
    }
}
if (valid) {
    if (adcs_wheel_momentum(wo_input.wheels, wo_input.count, &cluster_momentum) != ADCS_OK) {
        valid = 0;
    } else if (!adcs_is_finite_vec3(&cluster_momentum)) {
        valid = 0;
    }
}

/* Disable 复位历史与输出状态 */
if (wo_input.enable == 0) {
    wo_state.mode = WO_OFF;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.recovery_count = 0U;
    wo_state.history_initialized = 0;
    wo_state.previous_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    for (i = 0; i < 4U; i++) wo_state.previous_speed_rad_s[i] = 0.0;
    wo_output.mode = WO_OFF;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

/* 无效输入或配置：latch FAULT 并清零命令 */
if (!valid) {
    wo_state.mode = WO_FAULT;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.recovery_count = 0U;
    wo_state.history_initialized = 0;
    wo_state.previous_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

if (wo_state.mode == WO_FAULT) {
    /* 保持 FAULT，命令清零 */
    wo_output.mode = WO_FAULT;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = cluster_momentum;
    wo_output.momentum_norm = adcs_vec3_norm(&cluster_momentum);
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.clean = wo_state.clean;
    wo_output.elapsed = wo_state.elapsed;
    wo_output.recovery_count = wo_state.recovery_count;
    return;
}

/* 首次接受样本，历史速度初始化，零加速度 */
if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
    wo_state.history_initialized = 1;
}

/* 计算每个轮的加速度、预测速度、trip mask */
current_max = 0.0;
predicted_max = 0.0;
for (i = 0; i < 4U; i++) {
    double speed = wo_input.wheels[i].speed_rad_s;
    accel[i] = (speed - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
    predicted[i] = speed + accel[i] * wo_config.prediction_horizon_s;
    if (fabs(speed) > current_max) current_max = fabs(speed);
    if (fabs(predicted[i]) > predicted_max) predicted_max = fabs(predicted[i]);
    if (fabs(predicted[i]) >= wo_config.trip_rad_s) {
        predicted_trip_mask |= (unint32)(1U << i);
    }
}

/* 发布未门槛的输出字段 */
wo_output.maximum_speed = current_max;
wo_output.predicted_maximum_speed = predicted_max;
wo_output.momentum = cluster_momentum;
wo_output.momentum_norm = adcs_vec3_norm(&cluster_momentum);
for (i = 0; i < 4U; i++) {
    wo_output.acceleration_rad_s2[i] = accel[i];
    wo_output.predicted_speed_rad_s[i] = predicted[i];
}
wo_output.predicted_trip_mask = predicted_trip_mask;

/* 状态机 */
switch (wo_state.mode) {
case WO_OFF:
    if (predicted_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else if (predicted_max >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    }
    break;
case WO_WATCH:
    if (predicted_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else if (predicted_max < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
    }
    break;
case WO_ACTIVE:
    if (wo_state.elapsed < 0xFFFFFFFFU) wo_state.elapsed++;
    if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
        if ((current_max <= wo_config.release_rad_s) &&
            (predicted_max <= wo_config.release_rad_s)) {
            wo_state.clean++;
            if (wo_state.clean >= wo_config.release_cycles) {
                wo_state.mode = WO_RECOVERY;
                wo_state.clean = 0U;
                wo_state.recovery_count = 0U;
            }
        } else {
            wo_state.clean = 0U;
        }
    }
    break;
case WO_RECOVERY:
    if (predicted_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else {
        if (wo_state.recovery_count < 0xFFFFFFFFU) wo_state.recovery_count++;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            wo_state.mode = WO_OFF;
            wo_state.recovery_count = 0U;
            wo_state.clean = 0U;
        }
    }
    break;
default:
    break;
}

/* 命令计算 */
if (wo_state.mode == WO_ACTIVE) {
    torque_cmd = adcs_vec3_scale(&cluster_momentum, -wo_config.gain);
    axis_vals[0] = torque_cmd.x;
    axis_vals[1] = torque_cmd.y;
    axis_vals[2] = torque_cmd.z;
    for (i = 0; i < 3U; i++) {
        if (fabs(axis_vals[i]) > wo_config.torque_limit) {
            axis_vals[i] = (axis_vals[i] > 0.0 ? wo_config.torque_limit : -wo_config.torque_limit);
            saturation_mask |= (unint32)(1U << i);
        }
    }
    limited = (adcs_vec3_t){axis_vals[0], axis_vals[1], axis_vals[2]};
    prev_vals[0] = wo_state.previous_torque.x;
    prev_vals[1] = wo_state.previous_torque.y;
    prev_vals[2] = wo_state.previous_torque.z;
    axis_vals[0] = limited.x;
    axis_vals[1] = limited.y;
    axis_vals[2] = limited.z;
    for (i = 0; i < 3U; i++) {
        tmp = axis_vals[i] - prev_vals[i];
        if (fabs(tmp) > wo_config.torque_slew) {
            tmp = (tmp > 0.0 ? wo_config.torque_slew : -wo_config.torque_slew);
            slew_mask |= (unint32)(1U << i);
        }
        axis_vals[i] = prev_vals[i] + tmp;
    }
    wo_output.torque = (adcs_vec3_t){axis_vals[0], axis_vals[1], axis_vals[2]};
} else if (wo_state.mode == WO_RECOVERY) {
    prev_vals[0] = wo_state.previous_torque.x;
    prev_vals[1] = wo_state.previous_torque.y;
    prev_vals[2] = wo_state.previous_torque.z;
    axis_vals[0] = 0.0;
    axis_vals[1] = 0.0;
    axis_vals[2] = 0.0;
    for (i = 0; i < 3U; i++) {
        tmp = axis_vals[i] - prev_vals[i];
        if (fabs(tmp) > wo_config.torque_slew) {
            tmp = (tmp > 0.0 ? wo_config.torque_slew : -wo_config.torque_slew);
            slew_mask |= (unint32)(1U << i);
        }
        axis_vals[i] = prev_vals[i] + tmp;
    }
    wo_output.torque = (adcs_vec3_t){axis_vals[0], axis_vals[1], axis_vals[2]};
} else {
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
}

wo_output.saturation_mask = saturation_mask;
wo_output.slew_mask = slew_mask;
wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;

wo_state.previous_torque = wo_output.torque;
for (i = 0; i < 4U; i++) {
    wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
}

